import operator

def apply_op(name, a, b):
    ops = {'add': operator.add, 'sub': operator.sub, 'mul': operator.mul,
           'floordiv': operator.floordiv, 'mod': operator.mod, 'pow': operator.pow}
    return ops[name](a, b)

